import os
import subprocess
import threading
import paramiko
import time

from abc import ABC, abstractmethod
from datetime import datetime
from taf.rfrl.procedures.resources.python.logger import log_input_and_output
from .exceptions import XgenError, XgenClientNotFound, MissingSshParameters, StopXgenClientError, XgenClientStartError


class XgenClientRunner(ABC):
    def __init__(self, config: dict):
        self._logs_dir = config['logs_dir']
        self._xgen_server_ip = config['xgen_server_ip']
        self._xgen_client_path = config['xgen_client_path']
        self._xgen_client_log_path = os.path.join(self._logs_dir, 'xgen_client_logs')
        self._output_thread = None
        self._is_client_running = False

    @log_input_and_output
    def start_capture_pcap(self, ports, pcap_save_path, pcap_filter=None, pcap_filename="xgen_pcap.pcap"):
        """
        Starts capturing PCAP data using the xgen-client.
        :param ports: Ports to capture data from. Can be a single port as a string or a list of ports e.g. ["SFP1", "SFP2"].
        :type ports: str | list
        :param pcap_save_path: Directory where the PCAP file will be saved.
        :type pcap_save_path: str
        :param pcap_filter: (Optional) Filter to apply to the captured data. Default is None.
        :type pcap_filter: str | None
        :param pcap_filename: (Optional) Name of the PCAP file to be created with extension e.g. "xgen_capture.pcap". Default is "xgen_pcap.pcap".
        :type pcap_filename: str
        """
        if isinstance(ports, list):
            ports = ' '.join(ports)

        pcap_path = self._create_pcap_file_path(pcap_save_path, pcap_filename)
        filter_str = f" --filter '{pcap_filter}'" if pcap_filter else ""
        options = f"--capture {pcap_path} -cp {ports}{filter_str}"
        self._run_client(options)

    def _timestamp(self, time_format: str = "%Y-%m-%d %H:%M:%S") -> str:
        """
        Returns the current timestamp.
        :param time_format: (Optional) Format of the timestamp. Default is "%Y-%m-%d %H:%M:%S".
        :type time_format: str
        :return: Current timestamp as a string.
        """
        return datetime.now().strftime(time_format)

    def _log(self, stream_type, message: str):
        """
        Logs messages to the xgen-client log file.
        :param stream_type: Type of the stream (e.g., 'stdout', 'stderr').
        :param message: The message to log.
        """
        message_with_timestamp = f"{self._timestamp()} [{stream_type}] - {message}\n"
        self._log_file.write(message_with_timestamp)
        self._log_file.flush()

    def _create_and_open_log(self) -> open:
        """
        Creates and opens a log file for the xgen-client.
        :return: File object for the log file.
        """
        if not os.path.exists(self._xgen_client_log_path):
            os.makedirs(self._xgen_client_log_path, exist_ok=True)
        log_file_name = f"{self._timestamp('%Y_%m_%d_%H_%M_%S')}_xgen_client.log"
        return open(os.path.join(self._xgen_client_log_path, log_file_name), 'a')

    @abstractmethod
    def stop_capture(self):
        pass

    @abstractmethod
    def close(self):
        pass

    @abstractmethod
    def check_client_exists(self):
        pass

    @abstractmethod
    def _run_client(self, options: str):
        pass

    @abstractmethod
    def _stop_client(self):
        pass

    @abstractmethod
    def _read_output(self):
        pass

    @abstractmethod
    def _create_pcap_file_path(self, pcap_save_path: str, pcap_filename: str) -> str:
        pass


class LocalXgenClient(XgenClientRunner):
    """
    Implementation of the XgenClientRunner for running xgen-client on the local VM.

    Example:
        config = {
            'logs_dir': '/tmp/xgen_logs',
            'xgen_server_ip': '192.168.1.100',
            'xgen_client_path': '/usr/local/bin/xgen-client',
            'xgen_capture_ports': ['SFP1', 'SFP2']
        }
        client = LocalXgenClient(config)
        client.start_capture_pcap(['SFP1'], '/tmp/pcaps')
        client.stop_capture()
        client.close()
    """
    def __init__(self, config: dict):
        super().__init__(config)
        self.check_client_exists()

    @log_input_and_output
    def check_client_exists(self):
        """
        Checks if the xgen-client exists on the local VM.

        :raises FileNotFoundError: If xgen-client is not found at the specified path on the local VM.
        """
        result = subprocess.run(f'which {self._xgen_client_path}', shell=True, capture_output=True, text=True)
        if result.returncode != 0:
            raise XgenClientNotFound(f"xgen-client not found in '{os.path.dirname(self._xgen_client_path)}' directory.")

    @log_input_and_output
    def stop_capture(self):
        """
        Stops the xgen-client capture PCAP process running on the local VM.
        """
        self._stop_client()

    @log_input_and_output
    def close(self):
        """
        Stops the output thread if it is running.
        """
        if self._output_thread and self._output_thread.is_alive():
            self._output_thread.join(timeout=5)

    @log_input_and_output
    def _run_client(self, options: str):
        """
        Starts the xgen-client process on the local VM with the specified options.

        :param options: Options to pass to the xgen-client command. e.g. to capture PCAP data: "--capture {pcap_path} -cp {ports}{filter_str}"
        :type options: str
        :raises XgenClientStartError: If the xgen-client fails to start or is not running.
        """
        command = f"{self._xgen_client_path} -H {self._xgen_server_ip} {options}"
        self._log_file = self._create_and_open_log()
        try:
            self._process = subprocess.Popen(
                command,
                shell=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True
            )
            time.sleep(1)
            if self._process.poll():
                stdout, stderr = self._process.communicate()
                raise XgenClientStartError(
                    f"Failed to start xgen-client locally.\n"
                    f"Executed command: {command}\n"
                    f"Error from stdout: {stdout}\n"
                    f"Error from stderr: {stderr}"
                )
            self._is_client_running = True
            self._output_thread = threading.Thread(target=self._read_output)
            self._output_thread.start()
        except XgenError as e:
            raise XgenClientStartError(f"Failed to start xgen-client locally: {e}")

    @log_input_and_output
    def _stop_client(self):
        """
        Stops the xgen-client process on the local VM by sending Ctrl+C.
        Stops the output thread if it is running.
        Closes the log file.

        :raises StopXgenClientError: If the xgen-client is not running or fails to stop.
        """
        if not self._is_client_running:
            raise StopXgenClientError("xgen-client is not running. Cannot stop it.")

        try:
            self._process.send_signal(2)  # Send Ctrl+C
            self._output_thread.join(timeout=5)
            self._is_client_running = False
            self._log('stdout', "xgen-client process has been stopped.")
        except XgenError as e:
            raise StopXgenClientError(f"Failed to stop xgen-client: {e}")

    def _read_output(self):
        """
        Reads the output from the xgen-client process running on the local VM.

        :raises StopXgenClientError: If the xgen-client is not running or fails to read output.
        """
        if not self._is_client_running:
            raise StopXgenClientError("xgen-client is not running. Cannot read output.")

        while self._is_client_running and self._process:
            stdout_line = self._process.stdout.readline()
            if stdout_line:
                self._log('stdout', stdout_line.strip())
            stderr_line = self._process.stderr.readline()
            if stderr_line:
                self._log('stderr', stderr_line.strip())
            if self._process.poll():
                self._is_client_running = False
                self._log('stdout', "xgen-client process has been terminated.")
                break
            time.sleep(0.1)

    @log_input_and_output
    def _create_pcap_file_path(self, pcap_save_path: str, pcap_filename: str) -> str:
        """
        Creates the absolute path where the captured PCAP will be stored on local VM.

        :param pcap_save_path: Directory where the PCAP file will be saved on local VM.
        :type pcap_save_path: str
        :param pcap_filename: Name of the PCAP file with extension e.g. "xgen_capture.pcap".
        :type pcap_filename: str
        :return: Absolute path to the PCAP file.
        """
        return os.path.join(pcap_save_path, f"{pcap_filename}")


class RemoteXgenClient(XgenClientRunner):
    """
    Implementation of the XgenClientRunner for running xgen-client on a remote VM via SSH.

    Example:
        config = {
            'logs_dir': '/tmp/xgen_logs',
            'xgen_server_ip': '192.168.1.100',
            'xgen_client_path': '/usr/local/bin/xgen-client',
            'xgen_capture_ports': ['SFP1', 'SFP2'],
            'proxy_ssh': {
                'host': '192.168.1.200',
                'username': 'user',
                'password': 'pass'
            }
        }
        client = RemoteXgenClient(config)
        client.start_capture_pcap(['SFP1'], '/tmp/pcaps')
        client.stop_capture()
        client.close()
    """
    def __init__(self, config: dict):
        super().__init__(config)
        self._pcap_remote_path = None
        self._pcap_remote_filename = "xgen_pcap.pcap"
        self._pcap_local_path = None
        self._proxy_ssh = config['proxy_ssh']
        self._ssh = self._connect_ssh()
        self._channel = None
        self.check_client_exists()

    @log_input_and_output
    def stop_capture(self):
        """
        Stops the xgen-client capture PCAP process running on the remote VM.
        Downloads the captured PCAP file to the local machine and removes it from the remote VM.
        """
        self._stop_client()
        self._download_pcap()
        self._remove_pcap()

    @log_input_and_output
    def check_client_exists(self):
        """
        Checks if the xgen-client exists on the remote VM.

        :raises FileNotFoundError: If xgen-client is not found at the specified path on the remote VM.
        """
        _, stdout, _ = self._ssh.exec_command(f'which {self._xgen_client_path}')
        if stdout.channel.recv_exit_status() != 0:
            raise XgenClientNotFound(
                f"xgen-client not found at {os.path.dirname(self._xgen_client_path)} on remote VM (IP: {self._proxy_ssh['host']}).")

    @log_input_and_output
    def close(self):
        """
        Closes the SSH connection and stops the output thread if it is running.
        """
        self._ssh.close()
        if self._output_thread and self._output_thread.is_alive():
            self._output_thread.join(timeout=5)

    @log_input_and_output
    def _run_client(self, options: str):
        """
        Starts the xgen-client process on the remote VM with the specified options.

        :param options: Options to pass to the xgen-client command. e.g. to capture PCAP data: "--capture {pcap_path} -cp {ports}{filter_str}"
        :type options: str
        :raises XgenClientStartError: If the xgen-client fails to start or is not running.
        """
        if not self._ssh:
            raise ConnectionError("SSH connection is not established. Cannot run xgen-client.")

        self._create_ssh_channel()
        command = f"{self._xgen_client_path} -H {self._xgen_server_ip} {options}"
        self._channel.exec_command(command)
        time.sleep(1)
        if self._channel.exit_status_ready():
            raise XgenClientStartError(f"Failed to start xgen-client on remote VM.\n"
                                       f"Executed command: {command}\n"
                                       f"Error from stdout: {self._channel_stdout_err.read().decode('utf-8')}")

        self._log_file = self._create_and_open_log()
        self._is_client_running = True
        self._output_thread = threading.Thread(target=self._read_output)
        self._output_thread.start()

    @log_input_and_output
    def _stop_client(self):
        """
        Stops the xgen-client process on the remote VM.

        :raises StopXgenClientError: If the xgen-client is not running or fails to stop.
        """
        if self._channel and self._is_client_running:
            self._channel.send("\x03")  # Send Ctrl+C to stop the process
            time.sleep(5)
            self._is_client_running = False
            self._output_thread.join(timeout=5)
            self._channel.close()

        else:
            raise StopXgenClientError("Could not stop xgen-client process. It may not be running or the channel is not initialized.")

    @log_input_and_output
    def _connect_ssh(self) -> paramiko.SSHClient:
        """
        Initializes an SSH connection to the remote VM.

        :return: An SSHClient instance connected to the remote VM.
        :raises ConnectionError: If the connection to the remote VM fails.
        """
        try:
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh.connect(hostname=self._proxy_ssh['host'], username=self._proxy_ssh['username'], password=self._proxy_ssh['password'])
            return ssh
        except KeyError as e:
            raise MissingSshParameters(f"Missing required SSH connection parameters in 'proxy_ssh'. {e}")
        except Exception as e:
            raise ConnectionError(f"Failed to connect to remote VM (IP: {self._proxy_ssh['host']}): {e}")

    def _read_output(self):
        """
        Reads the output from the xgen-client process running on the remote VM.
        """
        while self._is_client_running and self._channel:
            if self._channel.recv_ready():
                output = self._channel.recv(1024).decode('utf-8')
                if output:
                    self._log('stdout', output.strip())
            if self._channel.exit_status_ready():
                self._is_client_running = False
                self._log('stdout', "xgen-client process has been terminated.")
                break
            time.sleep(0.1)

    def _create_ssh_channel(self):
        """
        Creates an SSH channel for executing commands on the remote VM.

        :return: An SSH channel instance.
        """
        self._channel = self._ssh.get_transport().open_session()
        self._channel.get_pty()
        self._channel.set_combine_stderr(True)
        self._channel_stdout_err = self._channel.makefile("r")

    @log_input_and_output
    def _download_pcap(self):
        """
        Downloads the captured PCAP file from the remote VM to the local machine "logs_dir" directory provided in config.

        :raises FileNotFoundError: If the PCAP file cannot be downloaded from the remote VM.
        """
        sftp = self._ssh.open_sftp()
        try:
            sftp.get(self._pcap_remote_path, self._pcap_local_path)
        except Exception as e:
            raise FileNotFoundError(f"Failed to download PCAP file: {e}")
        finally:
            sftp.close()

    def _remove_pcap(self):
        """
        Removes the captured PCAP file from the remote VM.

        :raises FileNotFoundError: If the PCAP file cannot be removed from the remote VM.
        """
        try:
            self._ssh.exec_command(f'rm {self._pcap_remote_path}')
        except Exception as e:
            raise FileNotFoundError(f"Failed to remove PCAP file from remote VM: {e}")

    @log_input_and_output
    def _create_pcap_file_path(self, pcap_save_path: str, pcap_filename: str) -> str:
        """
        Creates the absolute path where the captured PCAP will be stored on remote and local VM.

        :param pcap_save_path: Absolute directory where the PCAP file will be saved on local VM.
        :type pcap_save_path: str
        :param pcap_filename: Name of the PCAP file to be created with extension e.g. "xgen_capture.pcap".
        :type pcap_filename: str
        :return Absolute path to the PCAP file.
        """
        self._pcap_local_path = os.path.join(pcap_save_path, pcap_filename)
        if not os.path.exists(pcap_save_path):
            os.makedirs(pcap_save_path, exist_ok=True)
        self._pcap_remote_path = os.path.join(os.path.dirname(self._xgen_client_path), self._pcap_remote_filename)
        return self._pcap_remote_path
